import React, { useContext, useEffect, useState } from "react";
import ShowNotifications from "./components/showNotifications";
import NoticeThread from "./components/NoticeThread";
import { AuthContext } from "../../context/AuthContext";
import Loader from "../../components/Loader";
import toast, { Toaster } from "react-hot-toast";
import { 
  Container, 
  Row, 
  Col, 
  Card, 
  Form, 
  Button, 
  Nav,
  InputGroup
} from "@themesberg/react-bootstrap";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { 
  faSearch,
  faBriefcase,
  faChartLine,
  faListAlt,
  faBell,
  faCalendarAlt,
  faExclamationTriangle,
  faThumbtack
} from "@fortawesome/free-solid-svg-icons";
import "./CompanyNotifications.css";
import { IconProp } from "@fortawesome/fontawesome-svg-core";
import { filtersType, NoticeType } from "../../types/notice";
import { securedAxiosInstance } from "../../axiosConfig";

if ("Notification" in window) {
  Notification.requestPermission().then((permission) => {
    if (permission === "denied") {
      toast.error("Allow notification in site setting to stay updated!");
    }
  });
}

const CompanyNotifications = () => {
  const { state } = useContext(AuthContext);
  const { isLoading } = state;
  const [activeFilter, setActiveFilter] = useState<filtersType>("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("");
  const [selectedTag, setSelectedTag] = useState<string | undefined>(undefined);
  const [tags, setTags] = useState<Set<string>>(new Set());

  // Debounce search query
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery);
    }, 300);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  useEffect(() => {
    const fetchTags = async () => {
      const response = await securedAxiosInstance.get<string[]>(`/announcements/subtypes/${activeFilter}`);
      if (response.data != null && response.data != undefined) {
        setTags(new Set(response.data.filter((e: string) => e != null && e != undefined && e.trim() != "")));
      }
    };
    fetchTags();
  }, [activeFilter]);

  useEffect(() => {
    if (state?.profileData?.banStatus === true) {
      toast.error(
        "You are banned from this platform. Please contact the admin."
      );
    }
  }, []);

  const filterTabs: { id: filtersType, label: string, icon?: IconProp }[] = [
    { id: "All", label: "All" },
    { id: "CompanyEvent", label: "Company Event", icon: faChartLine },
    { id: "General", label: "General", icon: faListAlt },
  ];

  const handleFilterClick = (filterId: filtersType) => {
    setActiveFilter(filterId);
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
  };

  const handleSubtypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedTag(e.target.value);
  };

  // Map extended filter types to original filter types for ShowNotifications component
  const mapToOriginalFilter = (filter: filtersType): filtersType => {
    switch (filter) {
      case "CompanyEvent":
        return "CompanyEvent";
      case "General":
        return "General";
      default:
        return "All";
    }
  };

  if (isLoading) return <Loader />;

  return (
    <>
      <Toaster position="top-right" reverseOrder={false} />
      <Container fluid className="px-0" style={{ backgroundColor: 'transparent', minHeight: '100vh' }}>
        <Container style={{ maxWidth: '80vw' }}>
          <Row className="justify-content-center">
            <Col>
              <Card className="border-0 mt-3" style={{ backgroundColor: 'transparent' }}>
                <Card.Header className="bg-transparent border-0 py-4">
                  {/* Title Section */}
                  <Row className="mb-4">
                    <Col>
                      <h1 className="display-5 fw-bold text-dark mb-2">
                        🔔 Announcements
                      </h1>
                      <p className="text-muted fs-6 mb-0">
                        Stay updated with latest opportunities, placements, and important notices
                      </p>
                    </Col>
                  </Row>

                  {/* Search and Filter Controls */}
                  <Row className="mb-4 align-items-end">
                    <Col md={8} lg={9} className="mb-3 mb-md-0">
                      <InputGroup size="lg">
                        <InputGroup.Text className="bg-white border-end-0">
                          <FontAwesomeIcon icon={faSearch} className="text-muted" />
                        </InputGroup.Text>
                        <Form.Control
                          type="text"
                          placeholder="Search announcements, companies, or keywords..."
                          value={searchQuery}
                          onChange={handleSearchChange}
                          className="border-start-0"
                          style={{ fontSize: '16px', backgroundColor: 'white' }}
                        />
                      </InputGroup>
                    </Col>
                    <Col md={4} lg={3}>
                      <Form.Select
                        size="lg"
                        value={selectedTag}
                        onChange={handleSubtypeChange}
                        style={{ fontSize: '16px' }}
                      >
                        <option value="">Select a tag</option>
                        {Array.from(tags).map((subtype) => (
                          <option key={subtype} value={subtype}>
                            {subtype}
                          </option>
                        ))}
                      </Form.Select>
                    </Col>
                  </Row>

                  {/* Filter Tabs */}
                  <Nav variant="tabs" className="border-0" style={{backgroundColor: "transparent"}}>
                    {filterTabs.map((tab) => (
                      <Nav.Item key={tab.id} 
                      style={{
                        borderRadius: "10px",
                        display: "flex",
                        minWidth: "100px",
                        backgroundColor: activeFilter === tab.id ? "var(--bs-gray-400)" : "transparent",
                        margin: "4px",
                        justifyContent: "center",
                      }}
                      >
                        <Nav.Link
                          active={activeFilter === tab.id}
                          onClick={() => handleFilterClick(tab.id)}
                        style={{
                          backgroundColor: "transparent",
                          padding: "4px",
                          color: activeFilter === tab.id ? "black" : "#262b40"
                        }}
                        >
                          {tab.icon && (
                            <FontAwesomeIcon 
                              icon={tab.icon} 
                              className="me-2"
                              size="sm"
                            />
                          )}
                          {tab.label}
                        </Nav.Link>
                      </Nav.Item>
                    ))}
                  </Nav>
                </Card.Header>

                <Card.Body className="p-4">
                  <ShowNotifications 
                    searchQuery={debouncedSearchQuery}
                    activeFilter={mapToOriginalFilter(activeFilter)}
                    selectedTag={selectedTag}
                  />
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Container>
      </Container>
    </>
  );
};

export default CompanyNotifications;
